.td-delete:hover:not(:disabled) {
  color: light-dark(#a92e2e, #ffaaaa);
}
.td-edit {
  flex: 1;
  min-width: 0;
  gap: 4px;
}
.td-edit input {
  width: 0;
  flex: 1;
  min-width: 0;
  border: 1px solid var(--td-edge);
  border-radius: 6px;
  padding: 6px 8px;
  background: var(--td-panel);
  color: var(--td-text);
}
.td-completed {
  margin-top: 16px;
}
.td-disclosure {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 4px;
  border: 0;
  border-radius: 6px;
  color: var(--td-muted);
  background: transparent;
  font-size: 12px;
}
.td-disclosure span {
  font-variant-numeric: tabular-nums;
}
.td-empty {
  padding: 48px 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  color: var(--td-muted);
  text-align: center;
}
.td-empty svg {
  opacity: 0.6;
  margin-bottom: 14px;
}
.td-empty strong {
  color: var(--td-text);
  font-size: 15px;
  font-weight: 500;
}
.td-empty p {
  margin: 6px 0 0;
  font-size: 13px;
}
.td-error {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px;
  margin-top: 12px;
  border-radius: 8px;
  color: light-dark(#9d3030, #ffb1b1);
  background: light-dark(#fff3f3, #b423181a);
}
.td-error span {
  flex: 1;
  overflow-wrap: anywhere;
}
.td-error button:not(.td-icon) {
  border: 0;
  background: transparent;
  color: inherit;
  white-space: nowrap;
  text-decoration: underline;
}
.td-loading,
.td-feedback {
  color: var(--td-muted);
  font-size: 12px;
}
.td-feedback {
  min-height: 18px;
  margin-top: 14px;
}
@media (max-width: 480px) {
  .td-app {
    padding: 20px 16px;
  }
  .td-header {
    margin-bottom: 20px;
  }
  .td-filters button {
    gap: 5px;
    padding: 6px 8px;
  }
}

